/** Canonical memory or access form constructor. */
export type Form =
    /** Automatically managed runtime value, the unqualified `User`. */
    | {
          readonly kind: "managed";
      }
    /** Owned value, like `^User`. */
    | {
          readonly kind: "owned";
      }
    /** Borrowed value, like `&User`, `&readonly User`, or `&exclusive User`. */
    | {
          readonly kind: "borrowed";
          /** The solved borrow lifetime singleton. */
          readonly lifetime: GlobalTypeId;
          /** The solved borrow access singleton. */
          readonly access: GlobalTypeId;
      }
    /** Raw pointer value, like `*User`. */
    | {
          readonly kind: "raw";
      }
    /** Placed value, like `local User` or `shared User`. */
    | {
          readonly kind: "placed";
          /** The solved concrete or ambient place singleton. */
          readonly place: GlobalTypeId;
      }
    /** Readonly view, like `readonly User`. */
    | {
          readonly kind: "readonly";
      }
;

export const Form = {
    /** Automatically managed runtime value, the unqualified `User`. */
    managed(): Form {
        return { kind: "managed" };
    },

    /** Owned value, like `^User`. */
    owned(): Form {
        return { kind: "owned" };
    },

    /** Borrowed value, like `&User`, `&readonly User`, or `&exclusive User`. */
    borrowed(lifetime: GlobalTypeId, access: GlobalTypeId): Form {
        return { kind: "borrowed", lifetime, access };
    },

    /** Raw pointer value, like `*User`. */
    raw(): Form {
        return { kind: "raw" };
    },

    /** Placed value, like `local User` or `shared User`. */
    placed(place: GlobalTypeId): Form {
        return { kind: "placed", place };
    },

    /** Readonly view, like `readonly User`. */
    "readonly"(): Form {
        return { kind: "readonly" };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: Form): void {
        encodeForm(writer, value);
    },

    /** Decode one Form. */
    decode(reader: BinaryReader): Form {
        return decodeForm(reader);
    },

    /** Return this value as JSON. */
    toJson(value: Form): Json {
        return toJsonForm(value);
    },

    /** Return one Form from one JSON value. */
    fromJson(value: Json): Form {
        return fromJsonForm(value);
    },
};

/** Encode one Form. */
export function encodeForm(writer: BinaryWriter, value: Form): void {
    switch (value.kind) {
        case "managed":
            writer.writeUnsigned(0);
            return;
        case "owned":
            writer.writeUnsigned(1);
            return;
        case "borrowed":
            writer.writeUnsigned(2);
            encodeGlobalTypeId(writer, value.lifetime);
            encodeGlobalTypeId(writer, value.access);
            return;
        case "raw":
            writer.writeUnsigned(3);
            return;
        case "placed":
            writer.writeUnsigned(4);
            encodeGlobalTypeId(writer, value.place);
            return;
        case "readonly":
            writer.writeUnsigned(5);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one Form. */
export function decodeForm(reader: BinaryReader): Form {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            return { kind: "managed" };
        }
        case 1: {
            return { kind: "owned" };
        }
        case 2: {
            const lifetime = decodeGlobalTypeId(reader);
            const access = decodeGlobalTypeId(reader);

            return {
                kind: "borrowed",
                lifetime,
                access,
            };
        }
        case 3: {
            return { kind: "raw" };
        }
        case 4: {
            const place = decodeGlobalTypeId(reader);

            return {
                kind: "placed",
                place,
            };
        }
        case 5: {
            return { kind: "readonly" };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one Form. */
export function toJsonForm(value: Form): Json {
    switch (value.kind) {
        case "managed":
            return {
                kind: "managed",
            };
        case "owned":
            return {
                kind: "owned",
            };
        case "borrowed":
            return {
                kind: "borrowed",
                lifetime: toJsonGlobalTypeId(value.lifetime),
                access: toJsonGlobalTypeId(value.access),
            };
        case "raw":
            return {
                kind: "raw",
            };
        case "placed":
            return {
                kind: "placed",
                place: toJsonGlobalTypeId(value.place),
            };
        case "readonly":
            return {
                kind: "readonly",
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one Form from one JSON value. */
export function fromJsonForm(value: Json): Form {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "managed":
            return {
                kind,
            };
        case "owned":
            return {
                kind,
            };
        case "borrowed":
            return {
                kind,
                lifetime: fromJsonGlobalTypeId(jsonField(object, "lifetime")),
                access: fromJsonGlobalTypeId(jsonField(object, "access")),
            };
        case "raw":
            return {
                kind,
            };
        case "placed":
            return {
                kind,
                place: fromJsonGlobalTypeId(jsonField(object, "place")),
            };
        case "readonly":
            return {
                kind,
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}

