/** Encode one StringMapping. */
export function encodeStringMapping(writer: BinaryWriter, value: StringMapping): void {
    switch (value) {
        case "uppercase":
            writer.writeUnsigned(0);
            return;
        case "lowercase":
            writer.writeUnsigned(1);
            return;
        case "capitalize":
            writer.writeUnsigned(2);
            return;
        case "uncapitalize":
            writer.writeUnsigned(3);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

